method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    requires forall e :: e in extensions ==> e != ""
    ensures result == class_name + "." + strongestExtension
    ensures strongestExtension in extensions
    ensures forall e :: e in extensions && e != strongestExtension ==> strength(e) <= strength(strongestExtension)
{
    var strongestExtension := extensions[0];
    var maxStrength := strength(strongestExtension);

    // Iterate through the extensions to find the strongest one.
    var i := 1;
    while i < extensions.Length
        invariant 0 <= i <= extensions.Length
        invariant strongestExtension in extensions
        invariant maxStrength == strength(strongestExtension)
    {
        var currentStrength := strength(extensions[i]);
        if currentStrength > maxStrength {
            strongestExtension := extensions[i];
            maxStrength := currentStrength;
        }
        i := i + 1;
    }
    result := class_name + "." + strongestExtension;
}

// Helper function to calculate strength of an extension
method strength(extension: string) returns (s: int)
    requires extension != ""
    ensures s == CountUpperCase(extension) - CountLowerCase(extension)
{
    s := CountUpperCase(extension) - CountLowerCase(extension);
}

method CountUpperCase(s: string) returns (count: int)
    ensures count >= 0
{
    count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count >= 0
    {
        if Char.IsUpper(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
}

method CountLowerCase(s: string) returns (count: int)
    ensures count >= 0
{
    count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count >= 0
    {
        if Char.IsLower(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
}
